/* Sachgebiet 6: Umgang mit Menschen. Eigene prüfungsnahe Übungsfragen – keine Original-IHK-Fragen.
   Die Antworten beruhen auf gängigen Fachmodellen der Kommunikation und Deeskalation, nicht auf Rechtsnormen. */
SK.fragen("umm", [
  { u: "komm", d: 1, q: "Welche drei Kanäle der Kommunikation unterscheidet man?", o: ["Verbal, nonverbal und paraverbal", ["Schriftlich, telefonisch und digital", "Das sind Medien, keine Kanäle im Sinne des Modells."], ["Laut, leise und stumm", "Das beschreibt nur die Lautstärke."], ["Dienstlich, privat und öffentlich", "Das sind Anlässe, keine Kanäle."]], e: "Verbal ist der Wortinhalt, nonverbal die Körpersprache, paraverbal die Art des Sprechens (Tonfall, Tempo, Lautstärke)." },
  { u: "komm", d: 1, q: "Was gehört zur nonverbalen Kommunikation?", o: ["Mimik, Gestik, Körperhaltung und Blickkontakt", ["Die Wortwahl", "Das ist verbale Kommunikation."], ["Die Lautstärke der Stimme", "Das ist paraverbale Kommunikation."], ["Der Inhalt einer E-Mail", "Das ist verbale Kommunikation."]], e: "Die Körpersprache wirkt oft stärker als das gesprochene Wort – besonders, wenn beides nicht zusammenpasst." },
  { u: "komm", d: 2, q: "Was besagt der Satz „Man kann nicht nicht kommunizieren“ (Watzlawick)?", o: ["Jedes Verhalten hat Mitteilungscharakter – auch Schweigen oder Wegsehen.", ["Schweigen ist verboten.", "Der Satz beschreibt eine Wirkung, kein Verbot."], ["Nur Worte sind Kommunikation.", "Der Satz sagt das Gegenteil."], ["Kommunikation gelingt immer.", "Kommunikation kann misslingen."]], e: "Auch eine Wachperson, die demonstrativ wegsieht, sendet eine Botschaft." },
  { u: "komm", d: 2, q: "Welche vier Seiten hat eine Nachricht nach dem Modell von Schulz von Thun?", o: ["Sachinhalt, Selbstkundgabe, Beziehung, Appell", ["Frage, Antwort, Einwand, Schluss", "Das ist ein Gesprächsablauf, nicht das Vier-Seiten-Modell."], ["Sender, Empfänger, Kanal, Störung", "Das sind Elemente des Sender-Empfänger-Modells."], ["Wissen, Können, Wollen, Dürfen", "Das ist kein Kommunikationsmodell."]], e: "Jede Äußerung enthält alle vier Seiten. Missverständnisse entstehen, wenn der Empfänger auf einem anderen „Ohr“ hört, als der Sender meint." },
  { u: "komm", d: 2, f: 1, q: "Ein Besucher sagt gereizt: „Hier wartet man ja ewig!“ Auf welcher Ebene sollte die Wachperson zuerst reagieren, um zu deeskalieren?", o: ["Auf der Beziehungsebene: Verständnis zeigen und dann sachlich informieren", ["Auf der Sachebene: die exakte Wartezeit in Minuten korrigieren", "Eine reine Sachkorrektur wirkt belehrend und heizt an."], ["Gar nicht reagieren", "Ignorieren wird als Geringschätzung erlebt."], ["Mit einem Gegenvorwurf", "Das eskaliert."]], e: "Ärger sitzt auf der Beziehungsebene. Wer ihn anerkennt („Ich verstehe, dass das ärgerlich ist“), macht die Sachebene wieder zugänglich." },
  { u: "komm", d: 1, q: "Was ist aktives Zuhören?", o: ["Aufmerksam zuhören, ausreden lassen, nachfragen und das Gehörte mit eigenen Worten zusammenfassen", ["Während des Zuhörens die eigene Antwort vorbereiten", "Dann hört man nicht mehr wirklich zu."], ["Dem anderen ins Wort fallen, um Zeit zu sparen", "Unterbrechen signalisiert Desinteresse."], ["Nur nicken und nichts sagen", "Es fehlen Rückmeldung und Nachfragen."]], e: "Aktives Zuhören zeigt Wertschätzung und klärt Missverständnisse früh." },
  { u: "komm", d: 2, q: "Welche Formulierung ist eine Ich-Botschaft?", o: ["„Ich möchte, dass Sie Abstand halten – so kann ich Ihnen besser zuhören.“", ["„Sie sind unverschämt!“", "Das ist ein Vorwurf (Du-Botschaft)."], ["„Immer machen Sie Ärger!“", "Das ist eine verallgemeinernde Du-Botschaft."], ["„Jeder weiß, dass das verboten ist.“", "Das ist eine unpersönliche Verallgemeinerung."]], e: "Ich-Botschaften beschreiben die eigene Wahrnehmung und den eigenen Wunsch, ohne den anderen anzugreifen." },
  { u: "komm", d: 1, q: "Was ist eine offene Frage?", o: ["Eine Frage, die sich nicht mit Ja oder Nein beantworten lässt, z. B. „Was ist passiert?“", ["Eine Frage, die die Antwort schon vorgibt", "Das ist eine Suggestivfrage."], ["Eine Frage mit zwei vorgegebenen Antworten", "Das ist eine Alternativfrage."], ["Eine Frage, die man nicht stellen darf", "So ist der Begriff nicht definiert."]], e: "Offene Fragen (W-Fragen) bringen Informationen und lassen den anderen erzählen." },
  { u: "komm", d: 2, q: "Wann ist eine geschlossene Frage sinnvoll?", o: ["Wenn eine klare, kurze Entscheidung oder Bestätigung gebraucht wird", ["Wenn man möglichst viel erfahren will", "Dafür eignen sich offene Fragen."], ["Wenn man jemanden bloßstellen möchte", "Das ist kein legitimes Ziel."], ["Nie", "Geschlossene Fragen haben ihren Platz."]], e: "Beispiel: „Brauchen Sie einen Arzt?“ – in Stresssituationen sind einfache Ja/Nein-Fragen hilfreich." },
  { u: "komm", d: 2, q: "Welche Distanzzone sollte eine Wachperson im normalen dienstlichen Gespräch mit Fremden respektieren?", o: ["Die persönliche bis gesellschaftliche Distanz – etwa eine Armlänge und mehr", ["Die Intimdistanz unter einer halben Armlänge", "Das Eindringen in die Intimzone wird als Bedrohung erlebt."], ["Mindestens zehn Meter", "Das macht ein Gespräch unmöglich."], ["Die Distanz spielt keine Rolle", "Distanzverhalten beeinflusst die Wirkung erheblich."]], e: "Die Zonen sind Modellwerte und kulturell verschieden. Wer die Intimzone ungefragt unterschreitet, löst Abwehr aus." },
  { u: "komm", d: 2, f: 1, q: "Eine Wachperson sagt „Selbstverständlich helfe ich Ihnen gern“, verschränkt dabei die Arme und rollt mit den Augen. Was nimmt der Besucher vor allem wahr?", o: ["Die ablehnende Körpersprache – die Botschaft wirkt unglaubwürdig", ["Nur den freundlichen Wortinhalt", "Bei Widerspruch überwiegt meist das Nonverbale."], ["Gar nichts", "Solche Signale werden sehr wohl wahrgenommen."], ["Die Uhrzeit", "Das hat mit der Situation nichts zu tun."]], e: "Stimmen Wort und Körpersprache nicht überein (Inkongruenz), glaubt der Empfänger der Körpersprache." },
  { u: "komm", d: 1, q: "Wie spricht eine Wachperson eine unbekannte Person richtig an?", o: ["Höflich, mit Blickkontakt, in der Sie-Form, mit Gruß und kurzer Nennung des Anliegens", ["Mit „He, Sie da!“ aus der Entfernung", "Das wirkt herablassend."], ["Sofort mit einer Anschuldigung", "Das provoziert Widerstand."], ["Per Du, um locker zu wirken", "Das Du kann als respektlos empfunden werden."]], e: "Der erste Kontakt bestimmt den weiteren Verlauf. Respekt ist die beste Vorbeugung gegen Konflikte." },
  { u: "komm", t: "mc", d: 2, q: "Welche zwei Verhaltensweisen gehören zu einer guten Gesprächsführung in schwierigen Situationen?", o: ["Ruhig und deutlich sprechen", "Den anderen ausreden lassen", ["Lauter werden als das Gegenüber", "Das schaukelt die Situation auf."], ["Ironie einsetzen", "Ironie wird unter Stress als Angriff verstanden."]], e: "Ruhe überträgt sich – Lautstärke auch." },
  { u: "komm", t: "tf", d: 1, a: true, q: "Tonfall und Lautstärke können den Sinn einer Aussage völlig verändern.", e: "Das ist die paraverbale Ebene: Derselbe Satz kann freundlich, drohend oder ironisch klingen." },
  { u: "komm", t: "tf", d: 2, a: false, q: "Verstehen Sender und Empfänger dieselbe Sprache, sind Missverständnisse ausgeschlossen.", e: "Missverständnisse entstehen auch durch unterschiedliche Erfahrungen, Erwartungen und die Beziehungsebene." },
  { u: "komm", t: "zu", d: 2, q: "Ordne jede Aussage der passenden Seite der Nachricht „Die Ampel ist grün“ (Beifahrer zum Fahrer) zu.", p: [["Sachinhalt", "Die Ampel zeigt Grün."], ["Appell", "Fahr los!"], ["Beziehung", "Du brauchst meine Hilfe."], ["Selbstkundgabe", "Ich habe es eilig."]], e: "Das klassische Beispiel des Vier-Seiten-Modells." },
  { u: "komm", t: "fa", d: 2, q: "Erkläre das Vier-Seiten-Modell einer Nachricht an einem Beispiel aus dem Wachdienst.", m: "Jede Nachricht hat vier Seiten. Beispiel: Die Wachperson sagt zu einem Besucher: „Hier ist Rauchverbot.“ Sachinhalt: In diesem Bereich darf nicht geraucht werden. Selbstkundgabe: Ich achte auf die Einhaltung der Hausordnung. Beziehung: Ich bin hier zuständig und spreche Sie darauf an. Appell: Machen Sie die Zigarette aus. Der Besucher kann auf dem Beziehungsohr hören („Der will mich maßregeln“) und gereizt reagieren. Deshalb hilft eine freundliche Formulierung mit Begründung und Alternative: „Bitte rauchen Sie draußen, dort ist ein Aschenbecher.“", c: ["Sachinhalt", "Selbstkundgabe", "Beziehung", "Appell", "Beispiel mit Deutung", "Folgerung für die Formulierung"] },

  { u: "wahr", d: 2, q: "Was ist selektive Wahrnehmung?", o: ["Man nimmt bevorzugt wahr, was zu den eigenen Erwartungen und Interessen passt.", ["Man nimmt alles vollständig und objektiv wahr.", "Wahrnehmung ist immer eine Auswahl."], ["Man nimmt nur mit den Augen wahr.", "Der Begriff bezieht sich nicht auf einen Sinn."], ["Man nimmt absichtlich nichts wahr.", "Die Auswahl geschieht meist unbewusst."]], e: "Für Berichte bedeutet das: Wahrnehmung und Deutung trennen, Zeugen hinzuziehen." },
  { u: "wahr", d: 1, q: "Was ist ein Vorurteil?", o: ["Ein vorgefasstes, nicht überprüftes Urteil über Personen oder Gruppen", ["Ein Urteil eines Gerichts", "Das ist ein Rechtsbegriff."], ["Eine auf Erfahrung mit genau dieser Person gestützte Einschätzung", "Dann wäre es ein überprüftes Urteil."], ["Eine Dienstanweisung", "Das hat damit nichts zu tun."]], e: "Vorurteile steuern unbemerkt die Wahrnehmung und führen zu ungleicher Behandlung." },
  { u: "wahr", d: 2, q: "Was beschreibt der „erste Eindruck“?", o: ["In wenigen Sekunden entsteht ein Bild vom anderen, das spätere Wahrnehmungen färbt.", ["Er ist immer zutreffend.", "Er kann täuschen."], ["Er entsteht erst nach langen Gesprächen.", "Er entsteht sehr schnell."], ["Er hat keinen Einfluss auf das weitere Verhalten.", "Er prägt den weiteren Kontakt."]], e: "Das gilt in beide Richtungen: Auch die Wachperson wird in Sekunden eingeschätzt – Auftreten und Erscheinungsbild zählen." },
  { u: "wahr", d: 2, q: "Was versteht man unter Selbstbild und Fremdbild?", o: ["Wie ich mich selbst sehe und wie andere mich sehen – beides kann voneinander abweichen.", ["Ein Passfoto und ein Gruppenfoto", "Die Begriffe stammen aus der Psychologie."], ["Das Bild der Firma in der Presse", "Gemeint ist die Person."], ["Zwei Kameraperspektiven der Videoanlage", "Die Begriffe stammen aus der Psychologie."]], e: "Rückmeldungen von Kollegen helfen, das eigene Auftreten realistisch einzuschätzen." },
  { u: "wahr", d: 2, q: "Welche Bedürfnisse bilden in der Bedürfnispyramide nach Maslow die unterste Stufe?", o: ["Körperliche Grundbedürfnisse wie Essen, Trinken und Schlaf", ["Selbstverwirklichung", "Sie bildet die Spitze."], ["Anerkennung", "Sie liegt weiter oben."], ["Soziale Zugehörigkeit", "Sie liegt in der Mitte."]], e: "Reihenfolge: Grundbedürfnisse, Sicherheit, soziale Bedürfnisse, Anerkennung, Selbstverwirklichung." },
  { u: "wahr", d: 2, q: "Warum ist ein gesundes Selbstwertgefühl für Wachpersonen wichtig?", o: ["Wer sich seiner selbst sicher ist, kann ruhig, sachlich und ohne Machtgehabe auftreten.", ["Es berechtigt dazu, Anweisungen lauter zu erteilen.", "Lautstärke ist kein Zeichen von Selbstsicherheit."], ["Es ersetzt die Rechtskenntnis.", "Fachwissen bleibt nötig."], ["Es macht Kritik überflüssig.", "Selbstsichere Menschen können Kritik annehmen."]], e: "Überhebliches und unsicheres Verhalten haben oft dieselbe Wurzel: ein angegriffenes Selbstwertgefühl." },
  { u: "wahr", d: 2, f: 1, q: "Ein Kollege reagiert auf jede Rückfrage von Besuchern gereizt und betont ständig seine „Autorität“. Was ist eine wahrscheinliche Ursache?", o: ["Unsicherheit bzw. ein geringes Selbstwertgefühl, das durch Dominanz überspielt wird", ["Besonders große Fachkenntnis", "Fachkenntnis führt eher zu Gelassenheit."], ["Ein hohes Maß an Empathie", "Empathie zeigt sich anders."], ["Eine besonders gute Unterweisung", "Das erklärt das Verhalten nicht."]], e: "Überkompensation ist ein typisches Zeichen von Minderwertigkeitsgefühlen." },
  { u: "wahr", d: 1, q: "Was ist Empathie?", o: ["Die Fähigkeit, sich in die Lage und Gefühle eines anderen hineinzuversetzen", ["Die Fähigkeit, schnell zu rennen", "Das ist keine Empathie."], ["Das Recht, jemanden zu durchsuchen", "Das hat damit nichts zu tun."], ["Die Pflicht, jedem recht zu geben", "Empathie heißt verstehen, nicht zustimmen."]], e: "Empathie erleichtert es, Motive zu erkennen und angemessen zu reagieren." },
  { u: "wahr", t: "tf", d: 2, a: true, q: "Die eigene Stimmung beeinflusst, wie man das Verhalten anderer wahrnimmt und bewertet.", e: "Wer gereizt ist, deutet neutrale Signale schneller als Provokation." },
  { u: "wahr", t: "fa", d: 2, q: "Nenne typische Wahrnehmungsfehler und erkläre, wie du ihnen im Dienst begegnest.", m: "Typische Fehler sind selektive Wahrnehmung, der erste Eindruck, der Halo-Effekt (ein Merkmal überstrahlt alles andere), Vorurteile und Stereotype sowie die Erwartungshaltung: Man sieht, was man erwartet. Dagegen hilft: Beobachtung und Bewertung trennen; nur aufschreiben, was man selbst gesehen und gehört hat; eine zweite Person hinzuziehen; nachfragen statt unterstellen; die eigene Stimmung prüfen; alle Personen nach demselben Maßstab behandeln.", c: ["selektive Wahrnehmung", "erster Eindruck / Halo-Effekt", "Vorurteile", "Beobachtung und Deutung trennen", "Zweitmeinung, Nachfragen"] },

  { u: "konflikt", d: 1, q: "Was ist ein Konflikt?", o: ["Das Aufeinandertreffen gegensätzlicher Interessen, Ziele oder Bedürfnisse", ["Jede Unterhaltung zwischen zwei Personen", "Nicht jedes Gespräch ist ein Konflikt."], ["Ein technischer Defekt", "Das ist eine Störung."], ["Eine Straftat", "Ein Konflikt muss keine Straftat sein."]], e: "Konflikte sind normal. Entscheidend ist, wie sie ausgetragen werden." },
  { u: "konflikt", d: 2, q: "Was besagt die Frustrations-Aggressions-Annahme?", o: ["Wird jemand an der Erreichung eines Ziels gehindert, steigt die Bereitschaft zu aggressivem Verhalten.", ["Aggression entsteht nur durch Alkohol.", "Alkohol enthemmt, ist aber nicht die einzige Ursache."], ["Frustration führt immer zu körperlicher Gewalt.", "Aggression ist eine mögliche, keine zwingende Folge."], ["Aggression ist angeboren und nicht beeinflussbar.", "Die Annahme beschreibt gerade einen situativen Auslöser."]], e: "Typisch im Dienst: abgewiesene Gäste, lange Wartezeiten, Hausverbote." },
  { u: "konflikt", d: 2, f: 1, q: "Ein Gast wird an der Tür einer Diskothek abgewiesen und beginnt zu schimpfen. Was ist die wahrscheinlichste Ursache?", o: ["Frustration, weil er sein Ziel nicht erreicht und sich vor seinen Begleitern bloßgestellt fühlt", ["Er ist grundsätzlich ein gewalttätiger Mensch.", "Das ist ein vorschnelles Urteil über die Person."], ["Er möchte festgenommen werden.", "Das ist unwahrscheinlich."], ["Er hat die Hausordnung auswendig gelernt.", "Das erklärt das Verhalten nicht."]], e: "Wer die Ursache versteht, kann gegensteuern: sachlich begründen, Gesichtsverlust vermeiden, Alternative nennen." },
  { u: "konflikt", d: 2, q: "Woran erkennt man früh, dass ein Konflikt eskaliert?", o: ["Die Stimme wird lauter, der Abstand geringer, die Gestik heftiger, es fallen Beleidigungen.", ["Die Person setzt sich ruhig hin.", "Das spricht eher für Beruhigung."], ["Die Person bedankt sich.", "Das ist kein Eskalationszeichen."], ["Die Person stellt eine Sachfrage.", "Das spricht für Gesprächsbereitschaft."]], e: "Wer diese Signale früh erkennt, kann noch mit Worten gegensteuern." },
  { u: "konflikt", d: 2, q: "Welche Reaktion verschärft einen Konflikt am ehesten?", o: ["Den anderen vor Zuschauern bloßstellen", ["Sachlich bleiben", "Das beruhigt."], ["Eine Lösung anbieten", "Das beruhigt."], ["Zuhören", "Das beruhigt."]], e: "Wer das Gesicht verliert, kann kaum noch nachgeben. Gesichtswahrung ist ein Kernprinzip der Deeskalation." },
  { u: "konflikt", d: 2, q: "Welche Aggressionsformen unterscheidet man unter anderem?", o: ["Verbale Aggression, körperliche Aggression und Aggression gegen Sachen", ["Nur körperliche Aggression", "Auch Worte und Gesten können aggressiv sein."], ["Positive und negative Höflichkeit", "Das sind keine Aggressionsformen."], ["Private und dienstliche Müdigkeit", "Das sind keine Aggressionsformen."]], e: "Verbale Aggression geht körperlicher Gewalt häufig voraus – ein Warnsignal." },
  { u: "konflikt", d: 3, q: "Was ist ein typischer Fehler bei Provokationen?", o: ["Die Provokation persönlich nehmen und mit Gegenprovokation antworten", ["Ruhig bleiben", "Das ist richtig."], ["Das Verhalten sachlich benennen", "Das ist richtig."], ["Abstand halten", "Das ist richtig."]], e: "Provokationen zielen auf die Rolle, nicht auf die Person. Wer das trennt, bleibt handlungsfähig." },
  { u: "konflikt", t: "mc", d: 2, q: "Welche zwei Faktoren erhöhen die Aggressionsbereitschaft?", o: ["Alkohol- oder Drogeneinfluss", "Gruppendruck und Zuschauer", ["Ruhige, respektvolle Ansprache", "Sie senkt die Aggressionsbereitschaft."], ["Ausreichend Platz und Ausweichmöglichkeiten", "Sie senken die Aggressionsbereitschaft."]], e: "Weitere Faktoren: Hitze, Enge, Lärm, Wartezeiten, Gesichtsverlust." },
  { u: "konflikt", t: "tf", d: 1, a: false, q: "Konflikte lassen sich am besten lösen, indem man dem anderen beweist, dass er im Unrecht ist.", e: "Rechthaben verhärtet die Fronten. Wirksamer ist es, Interessen zu klären und eine für beide annehmbare Lösung zu suchen." },
  { u: "konflikt", t: "fa", d: 2, q: "Beschreibe, wie sich ein Konflikt typischerweise aufschaukelt, und woran du die Stufen erkennst.", m: "Am Anfang steht eine Meinungsverschiedenheit auf der Sachebene. Wird sie nicht gelöst, verlagert sich der Streit auf die Beziehungsebene: Vorwürfe, Verallgemeinerungen, lautere Stimme. Dann folgen Drohungen und Beleidigungen, der Abstand wird geringer, Unterstützer werden gesucht. Schließlich kommt es zu Gewalt gegen Sachen und Personen. Erkennbar ist das an Stimme, Wortwahl, Gestik, Distanz und Körperspannung. Je früher man eingreift, desto eher genügen Worte; auf den späten Stufen stehen Eigensicherung, Abstand und das Hinzuziehen von Unterstützung und Polizei im Vordergrund.", c: ["Sachebene → Beziehungsebene", "Drohung, Beleidigung", "Gewalt", "Erkennungszeichen", "frühes Eingreifen, später Eigensicherung"] },

  { u: "deesk", d: 1, q: "Was ist das Ziel der Deeskalation?", o: ["Eine angespannte Situation zu entschärfen und Gewalt zu verhindern", ["Den Streit zu gewinnen", "Es geht nicht ums Gewinnen."], ["Den anderen einzuschüchtern", "Einschüchterung eskaliert."], ["Möglichst schnell jemanden festzunehmen", "Das ist nicht das Ziel."]], e: "Deeskalation schützt alle Beteiligten – auch die Wachperson selbst." },
  { u: "deesk", t: "mc", d: 1, q: "Welche zwei Verhaltensweisen wirken deeskalierend?", o: ["Ruhige Stimme und offene Körperhaltung", "Dem Gegenüber einen gesichtswahrenden Ausweg anbieten", ["Mit dem Finger auf die Person zeigen", "Das wirkt bedrohlich."], ["Drohungen, die man nicht umsetzen kann", "Leere Drohungen untergraben die Glaubwürdigkeit."]], e: "Deeskalation beginnt bei der eigenen Haltung." },
  { u: "deesk", d: 2, f: 1, q: "Ein aufgebrachter Kunde schreit die Wachperson an. Welche Reaktion ist am besten?", o: ["Ruhig bleiben, Abstand halten, ausreden lassen, Verständnis signalisieren und dann eine Lösung anbieten", ["Zurückschreien, um Stärke zu zeigen", "Das schaukelt die Situation auf."], ["Den Kunden auslachen", "Das ist demütigend und eskaliert."], ["Den Kunden sofort am Arm packen", "Körperkontakt ohne Not eskaliert."]], e: "Wer schreit, will gehört werden. Zuhören nimmt Druck aus der Situation." },
  { u: "deesk", d: 2, q: "Welche Körperhaltung ist beim Gespräch mit einer erregten Person günstig?", o: ["Leicht seitlich versetzt, Hände sichtbar und offen, mit Abstand", ["Frontal und dicht vor der Person, Hände in den Hosentaschen", "Das wirkt konfrontativ und ist unsicher."], ["Mit verschränkten Armen und erhobenem Kinn", "Das wirkt ablehnend und überheblich."], ["Mit dem Rücken zur Person", "Das ist unhöflich und gefährlich."]], e: "Die seitliche Stellung wirkt weniger bedrohlich und ist zugleich sicherer." },
  { u: "deesk", d: 2, q: "Was bedeutet „gesichtswahrender Rückzug“?", o: ["Dem anderen eine Möglichkeit geben, nachzugeben, ohne sich gedemütigt zu fühlen", ["Sich selbst hinter einer Maske verstecken", "So ist der Begriff nicht gemeint."], ["Den anderen vor Publikum zur Entschuldigung zwingen", "Das bewirkt das Gegenteil."], ["Das Gespräch abbrechen und weggehen", "Gemeint ist der Ausweg für das Gegenüber."]], e: "Beispiel: „Kommen Sie, wir klären das kurz draußen in Ruhe“ – weg vom Publikum." },
  { u: "deesk", d: 2, q: "Welche Formulierung wirkt deeskalierend?", o: ["„Ich sehe, dass Sie verärgert sind. Lassen Sie uns schauen, was möglich ist.“", ["„Beruhigen Sie sich endlich!“", "Befehle zur Beruhigung bewirken meist das Gegenteil."], ["„Das ist mir völlig egal.“", "Das signalisiert Geringschätzung."], ["„Wenn Sie so weitermachen, werden Sie schon sehen.“", "Unbestimmte Drohungen eskalieren."]], e: "Gefühle benennen und ein Angebot machen – das sind zwei Grundtechniken." },
  { u: "deesk", d: 3, q: "Wann stößt Deeskalation an ihre Grenzen?", o: ["Wenn ein Angriff unmittelbar bevorsteht oder bereits stattfindet – dann haben Eigensicherung und Schutz anderer Vorrang.", ["Nie – man muss immer weiterreden.", "Bei einem Angriff ist Reden allein nicht mehr ausreichend."], ["Sobald jemand die Stimme erhebt", "Lautstärke allein ist noch kein Grund, die Deeskalation abzubrechen."], ["Sobald der Feierabend naht", "Das ist kein Kriterium."]], e: "Auch stark berauschte oder psychisch akut beeinträchtigte Personen sind mit Worten oft nicht erreichbar." },
  { u: "deesk", d: 2, f: 1, q: "Zwei Besucher streiten lautstark im Foyer. Wie geht die Wachperson am besten vor?", o: ["Die Streitenden ansprechen, räumlich trennen und einzeln ruhig anhören – möglichst mit einem Kollegen", ["Sich für eine Seite entscheiden und die andere zurechtweisen", "Parteinahme verschärft den Konflikt."], ["Abwarten, bis einer zuschlägt", "Dann ist es zu spät."], ["Beide anschreien, bis sie still sind", "Das eskaliert."]], e: "Trennen nimmt die Zuschauer und den Gegner aus dem Blickfeld; Neutralität erhält die Glaubwürdigkeit." },
  { u: "deesk", d: 2, q: "Warum sollte man angekündigte Konsequenzen auch umsetzen können?", o: ["Weil leere Drohungen die eigene Glaubwürdigkeit zerstören und zu weiteren Grenzüberschreitungen einladen", ["Weil Drohungen immer strafbar sind", "Das Ankündigen zulässiger Maßnahmen ist nicht strafbar."], ["Weil Konsequenzen nie nötig sind", "Sie können nötig sein."], ["Weil der Arbeitgeber es so will", "Der Grund liegt in der Wirkung."]], e: "Klar und realistisch: „Wenn Sie nicht gehen, rufe ich die Polizei“ – und es dann auch tun." },
  { u: "deesk", t: "tf", d: 1, a: true, q: "Deeskalation beginnt mit der Kontrolle der eigenen Gefühle.", e: "Nur wer selbst ruhig bleibt, kann beruhigend wirken." },
  { u: "deesk", t: "tf", d: 2, a: false, q: "Nachgeben ist immer ein Zeichen von Schwäche und im Wachdienst zu vermeiden.", e: "Wo ohne Schaden für den Auftrag ein Kompromiss möglich ist, ist Nachgeben professionell. Maßgeblich ist das Ziel, nicht der eigene Stolz." },
  { u: "deesk", t: "fa", d: 2, q: "Nenne Techniken der verbalen Deeskalation.", m: "Ruhig, langsam und deutlich sprechen; mit Namen bzw. höflich in der Sie-Form ansprechen; ausreden lassen und aktiv zuhören; Gefühle des anderen benennen und Verständnis zeigen, ohne in der Sache nachzugeben; Ich-Botschaften statt Vorwürfe; offene Fragen stellen; einfache, klare Sätze; Alternativen und einen gesichtswahrenden Ausweg anbieten; Zuschauer entfernen oder den Ort wechseln; Konsequenzen sachlich ankündigen statt drohen. Dazu gehören Abstand, offene Hände und eine seitliche Körperstellung.", c: ["ruhige Stimme", "aktives Zuhören", "Gefühle spiegeln", "Ich-Botschaften", "Auswege anbieten", "Publikum entfernen", "Abstand und Körpersprache"] },

  { u: "eigen", d: 1, q: "Was hat beim Einschreiten in einer Gefahrensituation Vorrang?", o: ["Die Eigensicherung", ["Die sofortige Festnahme", "Ohne Eigensicherung gefährdet man sich und andere."], ["Das Ausfüllen des Wachbuchs", "Dokumentiert wird danach."], ["Die Verfolgung um jeden Preis", "Sachwerte rechtfertigen keine Gefährdung des eigenen Lebens."]], e: "Nur wer selbst handlungsfähig bleibt, kann anderen helfen." },
  { u: "eigen", t: "mc", d: 2, q: "Welche zwei Maßnahmen gehören zur Eigensicherung?", o: ["Abstand halten und die Hände des Gegenübers beobachten", "Vor dem Einschreiten Kollegen oder Leitstelle informieren", ["Sich mit dem Rücken zur Wand in eine Ecke stellen lassen", "Dann fehlt der Fluchtweg."], ["Allein in unübersichtliche Räume nachgehen", "Das erhöht das Risiko."]], e: "Eigensicherung heißt: Überblick, Abstand, Rückzugsweg, Unterstützung." },
  { u: "eigen", d: 2, f: 1, q: "Bei einem nächtlichen Kontrollgang bemerkt die Wachperson eine aufgebrochene Tür und hört Geräusche im Gebäude. Was ist richtig?", o: ["Nicht allein hineingehen, sich in Sicherheit bringen, Leitstelle und Polizei verständigen und beobachten", ["Sofort allein hineingehen und die Täter stellen", "Das ist lebensgefährlich."], ["Laut rufen und die Tür von innen verriegeln", "Damit schließt man sich mit den Tätern ein."], ["Weitergehen und es am Morgen melden", "Die Meldung muss sofort erfolgen."]], e: "Täter können bewaffnet und in der Überzahl sein. Aufgabe ist Beobachten und Melden, nicht Heldentum." },
  { u: "eigen", d: 2, q: "Warum ist es wichtig, bei einer Ansprache einen Rückzugsweg zu haben?", o: ["Damit man sich bei einem Angriff in Sicherheit bringen kann", ["Damit man schneller Feierabend machen kann", "Darum geht es nicht."], ["Damit der andere nicht fliehen kann", "Es geht um den eigenen Fluchtweg."], ["Weil es die Hausordnung verlangt", "Der Grund ist die eigene Sicherheit."]], e: "Auch dem Gegenüber sollte der Weg nicht versperrt werden – wer sich eingekesselt fühlt, greift eher an." },
  { u: "eigen", d: 2, q: "Worauf achtet eine Wachperson bei der Annäherung an eine unbekannte Person besonders?", o: ["Auf Hände, Körperhaltung, mögliche gefährliche Gegenstände und weitere Personen im Umfeld", ["Auf die Marke der Kleidung", "Das ist für die Sicherheit unerheblich."], ["Auf die Frisur", "Das ist für die Sicherheit unerheblich."], ["Auf nichts – sie geht zügig hin", "Ohne Lagebeurteilung fehlt die Eigensicherung."]], e: "Gefahr geht meist von den Händen aus. Die Umgebung gehört zur Lagebeurteilung." },
  { u: "eigen", d: 3, f: 1, q: "Ein Mann droht im Eingangsbereich mit einem Messer. Was ist die richtige Reihenfolge?", o: ["Abstand vergrößern, andere warnen und wegführen, Polizei rufen, Täter beobachten", ["Auf den Mann zugehen und ihm das Messer abnehmen", "Das ist ohne Not lebensgefährlich."], ["Den Mann mit Worten provozieren, damit er einen Fehler macht", "Provokation erhöht die Gefahr."], ["Die Tür abschließen und mit ihm im Raum bleiben", "Damit nimmt man sich und anderen den Fluchtweg."]], e: "Bei Bewaffnung gilt: Distanz, Deckung, Alarmierung. Eingreifen nur als letztes Mittel in Notwehr oder Nothilfe." },
  { u: "eigen", t: "tf", d: 1, a: true, q: "Bei einer Streife zu zweit sichert eine Person, während die andere spricht.", e: "Diese Aufgabenteilung erhöht die Sicherheit: Der Sichernde beobachtet Umfeld und Hände und hält Abstand." },
  { u: "eigen", t: "fa", d: 2, q: "Was verstehst du unter professioneller Einsatzbewältigung? Beschreibe die Schritte.", m: "Erstens Lage erkennen und beurteilen: Was ist los, wer ist beteiligt, welche Gefahren bestehen? Zweitens Eigensicherung: Abstand, Überblick, Rückzugsweg, Meldung an Leitstelle oder Kollegen. Drittens Entschluss: Was ist mein Ziel, welches ist das mildeste Mittel? Viertens Handeln: ruhige Ansprache, klare Anweisungen, abgestimmtes Vorgehen im Team; wenn nötig Polizei oder Rettungsdienst. Fünftens Nachbereitung: Verletzte versorgen, Spuren sichern, Vorgang dokumentieren, Vorgesetzte informieren und den Einsatz im Team besprechen.", c: ["Lagebeurteilung", "Eigensicherung", "Entschluss / mildestes Mittel", "abgestimmtes Handeln", "Nachbereitung und Dokumentation"] },

  { u: "stress", d: 1, q: "Was ist Stress?", o: ["Eine körperliche und seelische Reaktion auf Anforderungen, die als belastend oder herausfordernd erlebt werden", ["Eine ansteckende Krankheit", "Stress ist keine Infektion."], ["Ein anderes Wort für Müdigkeit", "Müdigkeit kann eine Folge sein, ist aber nicht dasselbe."], ["Ein Rechtsbegriff aus dem BGB", "Der Begriff stammt aus Medizin und Psychologie."]], e: "Stress bereitet den Körper auf Kampf oder Flucht vor." },
  { u: "stress", d: 2, q: "Was unterscheidet Eustress von Distress?", o: ["Eustress wird als anregend erlebt, Distress als belastend und überfordernd.", ["Eustress ist stärker als Distress.", "Die Begriffe beschreiben die Bewertung, nicht die Stärke."], ["Distress tritt nur bei Kindern auf.", "Er betrifft alle Altersgruppen."], ["Es gibt keinen Unterschied.", "Die Begriffe unterscheiden positiven und negativen Stress."]], e: "Dieselbe Situation kann je nach Erfahrung und Vorbereitung als Herausforderung oder als Überforderung erlebt werden." },
  { u: "stress", t: "mc", d: 2, q: "Welche zwei körperlichen Reaktionen sind typisch für akuten Stress?", o: ["Schnellerer Herzschlag und angespannte Muskeln", "Eingeengte Wahrnehmung („Tunnelblick“)", ["Bessere Feinmotorik", "Die Feinmotorik verschlechtert sich."], ["Tiefe Entspannung", "Das Gegenteil ist der Fall."]], e: "Unter Stress sinkt die Fähigkeit zu überlegtem Handeln – eingeübte Abläufe helfen." },
  { u: "stress", d: 2, q: "Was hilft in einer akuten Stresssituation am ehesten, handlungsfähig zu bleiben?", o: ["Bewusst ruhig atmen und auf eingeübte Abläufe zurückgreifen", ["Schnell und flach atmen", "Das verstärkt die Stressreaktion."], ["Alle Entscheidungen sofort und ohne Nachdenken treffen", "Kurzes Innehalten verbessert die Entscheidung."], ["Die Situation ignorieren", "Das löst sie nicht."]], e: "Training und klare Handlungsabläufe sind die wirksamste Stressvorbeugung." },
  { u: "stress", d: 2, q: "Welche Stressoren sind für den Wachdienst typisch?", o: ["Schicht- und Nachtarbeit, Alleinarbeit, Konflikte mit Personen und lange Phasen der Monotonie", ["Zu viele Urlaubstage", "Das ist kein typischer Stressor."], ["Zu helle Büros", "Das ist kein typischer Stressor."], ["Zu häufige Gehaltserhöhungen", "Das ist kein Stressor."]], e: "Auch Unterforderung und Monotonie belasten und senken die Aufmerksamkeit." },
  { u: "stress", d: 2, q: "Welche Maßnahme dient der langfristigen Stressbewältigung?", o: ["Ausreichend Schlaf, Bewegung, soziale Kontakte und das Gespräch über belastende Einsätze", ["Regelmäßiger Alkoholkonsum zur Entspannung", "Das schadet und ist im Dienst verboten."], ["Belastungen möglichst verschweigen", "Das Verdrängen verstärkt die Belastung."], ["Dauerhaft Überstunden", "Das erhöht die Belastung."]], e: "Nach besonders belastenden Ereignissen sollte Nachsorge in Anspruch genommen werden." },
  { u: "stress", t: "tf", d: 2, a: true, q: "Unter starkem Stress neigen Menschen zu vorschnellen und unverhältnismäßigen Reaktionen.", e: "Deshalb ist Stress ein Auslöser von Fehlverhalten und Konflikten." },
  { u: "stress", t: "fa", d: 2, q: "Wie wirkt sich Stress auf das Verhalten im Einsatz aus, und was kannst du dagegen tun?", m: "Stress beschleunigt Puls und Atmung, spannt die Muskeln an und engt Wahrnehmung und Denken ein. Folgen können Tunnelblick, Überreaktion, Aggressivität, Fehler in der Kommunikation oder Erstarren sein. Kurzfristig helfen bewusstes Atmen, Abstand, ein kurzer Moment des Innehaltens, klare eingeübte Abläufe und die Unterstützung durch Kollegen. Langfristig helfen gute Vorbereitung und Training, Erholung, Bewegung, Austausch im Team und die Nachbereitung belastender Einsätze.", c: ["körperliche Reaktionen", "Tunnelblick, Überreaktion", "kurzfristig: Atmen, Abstand, Routine", "langfristig: Training, Erholung, Nachbereitung"] },

  { u: "gruppe", d: 2, q: "Was unterscheidet eine Menschenmasse von einer Gruppe?", o: ["In der Masse sind die Menschen einander weitgehend fremd; Anonymität senkt die Hemmschwelle.", ["Eine Masse hat immer einen gewählten Sprecher.", "Das kennzeichnet eher organisierte Gruppen."], ["In der Masse kennt jeder jeden.", "Das Gegenteil ist der Fall."], ["Es gibt keinen Unterschied.", "Die Begriffe sind zu unterscheiden."]], e: "In der Masse fühlt sich der Einzelne weniger verantwortlich; Stimmungen übertragen sich schnell." },
  { u: "gruppe", d: 2, q: "Was löst Panik in einer Menschenmenge typischerweise aus?", o: ["Eine tatsächliche oder vermeintliche Gefahr bei gleichzeitig eingeschränkten Fluchtmöglichkeiten", ["Zu viel Platz", "Enge, nicht Weite, begünstigt Panik."], ["Klare Lautsprecherdurchsagen", "Sie beugen Panik vor."], ["Gut beleuchtete Ausgänge", "Sie beugen Panik vor."]], e: "Panik entsteht, wenn Menschen glauben, nicht rechtzeitig entkommen zu können." },
  { u: "gruppe", t: "mc", d: 2, q: "Welche zwei Maßnahmen beugen Panik bei Veranstaltungen vor?", o: ["Flucht- und Rettungswege jederzeit frei halten", "Frühzeitig, ruhig und klar informieren", ["Ausgänge abschließen, damit niemand ohne Ticket hereinkommt", "Verschlossene Ausgänge sind lebensgefährlich."], ["Informationen zurückhalten, um niemanden zu beunruhigen", "Gerüchte und Unsicherheit fördern Panik."]], e: "Vertrauen entsteht durch sichtbare Präsenz und verständliche Ansagen." },
  { u: "gruppe", d: 2, f: 1, q: "In einer vollen Halle fällt der Strom aus, die Notbeleuchtung springt an. Die Menge wird unruhig. Wie handelt das Sicherheitspersonal richtig?", o: ["Ruhig und bestimmt auftreten, kurze klare Anweisungen geben und die Menschen zu den Ausgängen leiten", ["Nichts sagen und abwarten", "Fehlende Information verstärkt die Unruhe."], ["„Feuer!“ rufen, damit alle schneller gehen", "Das würde Panik auslösen."], ["Die Ausgänge blockieren, bis das Licht wieder da ist", "Das ist gefährlich."]], e: "Kurze, positive Anweisungen („Bitte gehen Sie ruhig zu den grünen Schildern“) geben Orientierung." },
  { u: "gruppe", d: 2, q: "Wie lenkt man Personenströme am wirksamsten?", o: ["Durch frühzeitige Leitung mit Absperrungen, Beschilderung, Durchsagen und sichtbarem Personal", ["Durch spontanes Zurückdrängen an Engstellen", "Gegendruck an Engstellen ist gefährlich."], ["Durch Schließen aller Zugänge ohne Ankündigung", "Das führt zu Stau und Druck."], ["Gar nicht – Menschen verteilen sich von selbst", "Ohne Lenkung entstehen gefährliche Verdichtungen."]], e: "Personenströme müssen vor Engstellen entzerrt werden, nicht in ihnen." },
  { u: "gruppe", d: 3, q: "Was ist bei gewaltbereiten Gruppen häufig zu beobachten?", o: ["Einzelne Wortführer heizen an, während sich andere im Schutz der Gruppe enthemmt verhalten.", ["Alle Mitglieder handeln völlig unabhängig voneinander.", "Gruppendynamik beeinflusst das Verhalten stark."], ["Gruppen sind grundsätzlich friedlicher als Einzelne.", "Das lässt sich so nicht sagen."], ["Wortführer wirken immer beruhigend.", "Sie können anheizen oder beruhigen."]], e: "Wer den Wortführer respektvoll anspricht und gewinnt, beruhigt oft die ganze Gruppe." },
  { u: "gruppe", d: 2, q: "Welche Aufgabe hat Sicherheitspersonal bei Großveranstaltungen typischerweise?", o: ["Einlasskontrolle, Freihalten der Rettungswege, Beobachtung der Besucherdichte und Meldung von Auffälligkeiten", ["Verkehrsregelung auf öffentlichen Straßen", "Das ist Aufgabe der Polizei."], ["Durchführung von Strafverfahren", "Das ist Aufgabe der Justiz."], ["Medizinische Behandlung Schwerverletzter", "Das ist Aufgabe des Rettungsdienstes; Erste Hilfe leistet jeder."]], e: "Grundlage sind Sicherheitskonzept, Hausordnung und die Absprachen mit Veranstalter, Polizei, Feuerwehr und Sanitätsdienst." },
  { u: "gruppe", t: "tf", d: 2, a: true, q: "Bei einer Evakuierung sind Aufzüge grundsätzlich nicht zu benutzen.", e: "Im Brandfall können Aufzüge ausfallen oder in den Brandbereich fahren. Hilfsbedürftige Personen werden unterstützt bzw. den Einsatzkräften gemeldet." },
  { u: "gruppe", t: "fa", d: 2, q: "Wie kommunizierst du mit Polizei, Feuerwehr und Rettungsdienst bei einem Einsatz im Objekt?", m: "Ich melde früh und eindeutig: Was ist wo passiert, wie viele Personen sind betroffen, welche Gefahren bestehen. Ich empfange die Einsatzkräfte an der Zufahrt oder lasse sie einweisen, übergebe Schlüssel, Pläne und Informationen zum Objekt und nenne einen festen Ansprechpartner. Ich schildere knapp die Lage und meine bisherigen Maßnahmen. Danach folge ich den Weisungen der Einsatzleitung, halte Zufahrten und Wege frei, halte Schaulustige fern und stehe für Rückfragen bereit.", c: ["klare Meldung", "Einweisung, Ansprechpartner", "Objektkenntnis weitergeben", "Weisungen folgen", "Wege freihalten"] },

  { u: "personen", d: 2, f: 1, q: "Ein stark betrunkener Mann sitzt schwankend auf der Treppe des Objekts und reagiert kaum auf Ansprache. Was ist zuerst zu tun?", o: ["Den Zustand prüfen: Ansprechen, Bewusstsein und Atmung kontrollieren und bei Bedarf den Rettungsdienst rufen", ["Ihn kommentarlos vor die Tür setzen", "Es könnte ein medizinischer Notfall vorliegen."], ["Ihn auslachen und fotografieren", "Das ist entwürdigend und unzulässig."], ["Ihn wachrütteln und anschreien", "Das hilft nicht und kann eskalieren."]], e: "Hilflose Personen dürfen nicht sich selbst überlassen werden – sonst droht unterlassene Hilfeleistung." },
  { u: "personen", d: 2, q: "Was ist im Umgang mit alkoholisierten Personen zu beachten?", o: ["Kurze, einfache Sätze, Geduld, Abstand – mit plötzlichen Stimmungswechseln rechnen", ["Lange Erklärungen der Rechtslage", "Sie werden nicht mehr aufgenommen."], ["Körperliche Nähe, um Vertrauen aufzubauen", "Die Reaktion ist unberechenbar."], ["Diskussionen über Schuld", "Sie führen zu nichts."]], e: "Alkohol enthemmt und mindert Einsicht und Schmerzempfinden." },
  { u: "personen", d: 2, q: "Wie verhält sich eine Wachperson gegenüber einer Person, die verwirrt wirkt und offenbar Stimmen hört?", o: ["Ruhig bleiben, Abstand halten, einfach und freundlich sprechen, nicht widersprechen oder lächerlich machen und Hilfe holen", ["Der Person erklären, dass sie verrückt ist", "Das verletzt und kann Angst auslösen."], ["Die Person festhalten, damit sie nichts anstellt", "Ohne Gefahr fehlt jede Grundlage; Festhalten kann Panik auslösen."], ["Die Person anschreien, damit sie zu sich kommt", "Das verstärkt die Angst."]], e: "Bei Eigen- oder Fremdgefährdung sind Polizei und Rettungsdienst zu verständigen." },
  { u: "personen", d: 2, q: "Welche Personen gelten in Unterkünften für Geflüchtete als besonders schutzbedürftig?", o: ["Unter anderem alleinreisende Frauen, Kinder, Menschen mit Behinderung, Opfer schwerer Gewalt sowie homosexuelle und transgeschlechtliche Personen", ["Nur Personen ohne Ausweis", "Der Schutzbedarf richtet sich nach der persönlichen Lage."], ["Nur Männer zwischen 20 und 30", "Diese Gruppe ist nicht als besonders schutzbedürftig genannt."], ["Niemand – alle sind gleich zu behandeln", "Gleichbehandlung schließt besonderen Schutz nicht aus."]], e: "Der Rahmenplan verlangt Handlungskompetenz im Umgang mit und zum Schutz von besonders schutzbedürftigen Geflüchteten." },
  { u: "personen", d: 2, f: 1, q: "In einer Unterkunft berichtet eine Bewohnerin der Wachperson, dass sie von einem Mitbewohner bedrängt wird. Wie handelt die Wachperson richtig?", o: ["Ernst nehmen, für sofortige Sicherheit sorgen, die Einrichtungsleitung bzw. zuständige Stelle informieren und den Vorfall dokumentieren", ["Ihr raten, dem Mann einfach aus dem Weg zu gehen", "Das nimmt die Schutzbedürftigkeit nicht ernst."], ["Den Mann vor allen Bewohnern zur Rede stellen", "Das gefährdet die Frau und eskaliert."], ["Nichts tun, weil es eine Privatangelegenheit ist", "Der Schutz der Bewohner gehört zum Auftrag."]], e: "Bei Verdacht auf eine Straftat ist die Polizei einzuschalten. Vertraulichkeit und Schutz der Betroffenen haben Vorrang." },
  { u: "personen", d: 1, q: "Wie geht man mit Kindern um, die im Einkaufszentrum ihre Eltern verloren haben?", o: ["Ruhig und freundlich ansprechen, auf Augenhöhe gehen, beim Kind bleiben und die Eltern ausrufen lassen", ["Das Kind allein zum Ausgang schicken", "Es darf nicht sich selbst überlassen werden."], ["Dem Kind Vorwürfe machen", "Das verängstigt es zusätzlich."], ["Das Kind im Büro einschließen", "Das ist unzulässig und verängstigt."]], e: "Nach Möglichkeit eine zweite Person hinzuziehen und das Kind nur an eindeutig Berechtigte übergeben." },
  { u: "personen", t: "tf", d: 2, a: false, q: "Bei einer Person unter Drogeneinfluss ist das Schmerzempfinden immer erhöht, sodass schon leichte Abwehr genügt.", e: "Das Schmerzempfinden kann stark herabgesetzt sein; die Reaktionen sind unberechenbar. Abstand und Unterstützung sind besonders wichtig." },
  { u: "personen", t: "zu", d: 2, q: "Ordne jeder Personengruppe das passende Vorgehen zu.", p: [["Stark Betrunkener", "kurze Sätze, Abstand, Gesundheitszustand prüfen"], ["Psychisch auffällige Person", "ruhig bleiben, nicht widersprechen, Hilfe holen"], ["Verlorenes Kind", "auf Augenhöhe, beruhigen, Eltern ausrufen"], ["Aufgebrachter Kunde", "zuhören, Verständnis zeigen, Lösung anbieten"]], e: "Professionelles Handeln passt sich der Person an." },
  { u: "personen", t: "fa", d: 3, q: "Worauf achtest du beim Dienst in einer Unterkunft für Geflüchtete besonders?", m: "Ich trete respektvoll, ruhig und unparteiisch auf und behandle alle Bewohner gleich. Ich berücksichtige, dass viele belastende Erfahrungen mit Gewalt und mit Uniformträgern gemacht haben; Dienstkleidung und autoritäres Auftreten können Angst auslösen. Ich achte auf besonders Schutzbedürftige – alleinreisende Frauen, Kinder, Menschen mit Behinderung, Opfer von Gewalt, homosexuelle und transgeschlechtliche Personen – und nehme Hinweise auf Übergriffe ernst. Ich wahre die Privatsphäre der Wohnbereiche, spreche einfach und nutze bei Bedarf Sprachmittler. Ich kenne meine Grenzen: keine hoheitlichen Maßnahmen, bei Straftaten und Gefahr Polizei und Leitung einschalten. Vorfälle dokumentiere ich sachlich.", c: ["Respekt und Neutralität", "belastende Vorerfahrungen", "besonders Schutzbedürftige", "Privatsphäre", "einfache Sprache / Sprachmittler", "keine Hoheitsrechte, Meldung, Dokumentation"] },

  { u: "kultur", d: 1, q: "Was bedeutet interkulturelle Kompetenz?", o: ["Die Fähigkeit, mit Menschen unterschiedlicher kultureller Prägung respektvoll und wirksam umzugehen", ["Die Kenntnis möglichst vieler Fremdsprachen", "Sprachkenntnisse helfen, sind aber nicht dasselbe."], ["Die Anpassung der Hausordnung an jede Kultur", "Regeln gelten für alle gleich."], ["Die Bevorzugung bestimmter Gruppen", "Kompetenz bedeutet gerade Gleichbehandlung."]], e: "Dazu gehören Wissen über Unterschiede, Offenheit und die Reflexion eigener Prägungen." },
  { u: "kultur", d: 2, q: "Worin können sich Kulturen in der Kommunikation unterscheiden?", o: ["Bei Blickkontakt, körperlicher Distanz, Gestik, Lautstärke und der Art, Kritik zu äußern", ["In gar nichts – Körpersprache ist überall gleich", "Viele Signale sind kulturell geprägt."], ["Nur in der Sprache", "Auch nonverbale Signale unterscheiden sich."], ["Nur in der Kleidung", "Das greift zu kurz."]], e: "Beispiel: Vermiedener Blickkontakt kann Respekt bedeuten und muss kein Zeichen von Unaufrichtigkeit sein." },
  { u: "kultur", d: 2, f: 1, q: "Ein Besucher spricht lauter und gestikuliert stärker, als die Wachperson es gewohnt ist. Wie sollte sie das zunächst einordnen?", o: ["Als möglichen kulturellen oder persönlichen Kommunikationsstil – nicht automatisch als Aggression", ["Als Angriff, der sofort abzuwehren ist", "Lautstärke und Gestik allein sind kein Angriff."], ["Als Beleidigung", "Das ist eine vorschnelle Deutung."], ["Als Zeichen von Alkoholisierung", "Das ist eine vorschnelle Deutung."]], e: "Erst beobachten und nachfragen, dann bewerten. Entscheidend sind Inhalt und Gesamtsituation." },
  { u: "kultur", d: 2, q: "Was verbietet das Allgemeine Gleichbehandlungsgesetz (AGG)?", o: ["Benachteiligungen aus Gründen der Rasse oder ethnischen Herkunft, des Geschlechts, der Religion oder Weltanschauung, einer Behinderung, des Alters oder der sexuellen Identität", ["Jede unterschiedliche Bezahlung", "Sachlich begründete Unterschiede bleiben möglich."], ["Das Aussprechen von Hausverboten", "Sachlich begründete Hausverbote bleiben zulässig."], ["Die Einlasskontrolle bei Veranstaltungen", "Kontrollen sind zulässig, wenn sie nicht diskriminierend erfolgen."]], e: "Das AGG nennt diese Merkmale in § 1. Es gilt im Arbeitsleben und bei Massengeschäften des täglichen Lebens.", r: "§ 1 AGG" },
  { u: "kultur", d: 2, f: 1, q: "Der Betreiber einer Diskothek weist die Türsteher an, „heute keine Ausländer“ einzulassen. Wie ist das zu bewerten?", o: ["Die Anweisung ist diskriminierend und rechtswidrig; sie darf nicht befolgt werden.", ["Sie ist vom Hausrecht gedeckt.", "Das Hausrecht findet seine Grenze im Diskriminierungsverbot."], ["Sie ist zulässig, wenn sie nur mündlich erteilt wird.", "Die Form ändert nichts."], ["Sie ist zulässig, wenn es schon voll ist.", "Dann wäre Überfüllung das Kriterium – für alle."]], e: "Zutrittsverweigerung wegen der ethnischen Herkunft verstößt gegen das AGG und kann Entschädigungsansprüche auslösen.", r: "§§ 1, 19, 21 AGG; Art. 3 GG" },
  { u: "kultur", d: 1, q: "Was versteht man unter Diversität?", o: ["Die Vielfalt von Menschen, z. B. nach Herkunft, Geschlecht, Alter, Religion, Behinderung und sexueller Identität", ["Die Zahl der Filialen eines Unternehmens", "Das ist nicht gemeint."], ["Unterschiedliche Dienstzeiten", "Das ist nicht gemeint."], ["Verschiedene Sicherheitstechniken", "Das ist nicht gemeint."]], e: "Der Rahmenplan verlangt, Diversität und gesellschaftliche Vielfalt im Umgang mit Menschen zu berücksichtigen." },
  { u: "kultur", d: 2, q: "Was ist ein Stereotyp?", o: ["Ein vereinfachtes, verallgemeinerndes Bild von einer Gruppe, das dem Einzelnen nicht gerecht wird", ["Ein Tonwiedergabegerät", "Das ist ein anderes Wort."], ["Eine Dienstvorschrift", "Das ist nicht gemeint."], ["Ein sicheres Erkennungsmerkmal für Täter", "Stereotype sind gerade keine verlässliche Grundlage."]], e: "Kontrollen dürfen sich am Verhalten orientieren, nicht an Gruppenzugehörigkeit." },
  { u: "kultur", d: 2, f: 1, q: "Bei der Einlasskontrolle sollen Personen abgetastet werden. Eine Besucherin möchte nicht von einem Mann abgetastet werden. Was ist angemessen?", o: ["Eine weibliche Kollegin hinzuziehen", ["Die Kontrolle trotzdem durch den Mann durchführen", "Das verletzt die Intimsphäre und ist zu vermeiden."], ["Die Besucherin ohne Kontrolle einlassen", "Die Kontrolle bleibt Zutrittsbedingung."], ["Die Besucherin wegen Verweigerung festhalten", "Ein Festnahmegrund besteht nicht."]], e: "Abtastkontrollen sollen durch Personen gleichen Geschlechts erfolgen. Ist das nicht möglich und lehnt die Person ab, bleibt nur die Verweigerung des Einlasses." },
  { u: "kultur", d: 3, f: 1, q: "Eine Wachperson hört, wie ein Kollege einen Besucher mit einem abwertenden Begriff für dessen Herkunft bezeichnet. Wie verhält sie sich richtig?", o: ["Sie spricht den Kollegen an, stellt klar, dass das nicht akzeptabel ist, und meldet den Vorfall bei Wiederholung oder Schwere dem Vorgesetzten.", ["Sie lacht mit, um das Betriebsklima nicht zu stören.", "Damit unterstützt sie die Diskriminierung."], ["Sie tut nichts, weil es sie nicht betrifft.", "Wegsehen duldet das Verhalten."], ["Sie beleidigt den Kollegen ebenfalls.", "Das löst das Problem nicht."]], e: "Diskriminierende Äußerungen können als Beleidigung strafbar sein und schaden dem Ansehen des Unternehmens." },
  { u: "kultur", t: "mc", d: 2, q: "Welche zwei Verhaltensweisen zeigen interkulturelle Kompetenz?", o: ["Bei Verständigungsproblemen langsam und einfach sprechen und Gesten oder Piktogramme nutzen", "Die eigenen Deutungen von Körpersprache hinterfragen", ["Lauter sprechen, damit man verstanden wird", "Lautstärke ersetzt keine Verständlichkeit und wirkt aggressiv."], ["Aus der Herkunft auf das Verhalten schließen", "Das ist ein Vorurteil."]], e: "Verständigung gelingt mit Geduld, einfachen Worten und Respekt." },
  { u: "kultur", t: "tf", d: 1, a: false, q: "Um niemanden zu diskriminieren, müssen für Besucher aus anderen Kulturen andere Hausregeln gelten.", e: "Regeln gelten für alle gleich. Interkulturelle Kompetenz zeigt sich in der Art, wie man sie erklärt und durchsetzt." },
  { u: "kultur", t: "fa", d: 2, q: "Erkläre, was Diskriminierung ist, und wie du sie im Dienst vermeidest.", m: "Diskriminierung ist die Benachteiligung eines Menschen wegen eines persönlichen Merkmals wie Herkunft, Hautfarbe, Geschlecht, Religion, Behinderung, Alter oder sexueller Identität, ohne dass es dafür einen sachlichen Grund gibt. Sie verstößt gegen Art. 3 GG und das AGG. Ich vermeide sie, indem ich alle nach denselben Regeln behandle, Kontrollen und Maßnahmen am Verhalten und nicht am Aussehen festmache, respektvoll spreche, abwertende Bemerkungen unterlasse und bei Kollegen nicht dulde, Entscheidungen sachlich begründe und meine eigenen Vorurteile hinterfrage.", c: ["Benachteiligung wegen persönlicher Merkmale", "Art. 3 GG, AGG", "gleiche Regeln für alle", "Verhalten statt Aussehen", "respektvolle Sprache", "eigene Vorurteile prüfen"] },

  { u: "fuehrung", d: 2, q: "Was kennzeichnet einen kooperativen Führungsstil?", o: ["Die Mitarbeiter werden in Entscheidungen einbezogen und erhalten Verantwortung.", ["Der Vorgesetzte entscheidet alles allein und duldet keinen Widerspruch.", "Das ist der autoritäre Stil."], ["Der Vorgesetzte kümmert sich um nichts.", "Das ist der Laissez-faire-Stil."], ["Es gibt keine Ziele.", "Auch kooperative Führung setzt Ziele."]], e: "Kooperative Führung fördert Motivation und Eigenverantwortung. In akuten Gefahrenlagen sind dagegen klare, direkte Anweisungen nötig." },
  { u: "fuehrung", d: 2, q: "Wozu dient ein Mitarbeitergespräch?", o: ["Zur Rückmeldung über Leistung und Verhalten, zur Klärung von Erwartungen und zur Vereinbarung von Zielen", ["Zur öffentlichen Bloßstellung von Fehlern", "Kritik erfolgt unter vier Augen."], ["Zur Weitergabe von Kundengeheimnissen", "Das wäre ein Verstoß gegen die Verschwiegenheit."], ["Ausschließlich zur Kündigung", "Das ist nicht der Zweck."]], e: "Das Mitarbeitergespräch ist ein Führungsinstrument – der Rahmenplan nennt es ausdrücklich." },
  { u: "fuehrung", d: 2, f: 1, q: "Als Schichtleiter bemerkst du, dass ein Mitarbeiter mehrfach zu spät zur Ablösung kommt. Wie gehst du vor?", o: ["Zeitnah unter vier Augen ansprechen, Gründe erfragen, Erwartung klar benennen und eine Vereinbarung treffen", ["Ihn vor der ganzen Schicht zurechtweisen", "Das beschämt und verschlechtert die Zusammenarbeit."], ["Nichts sagen und hoffen, dass es aufhört", "Das Problem bleibt bestehen und belastet die Kollegen."], ["Ihm kommentarlos schlechtere Dienste zuteilen", "Das ist keine offene Führung."]], e: "Kritik ist sachlich, konkret und auf das Verhalten bezogen – nicht auf die Person." },
  { u: "fuehrung", t: "tf", d: 2, a: true, q: "In einer akuten Gefahrensituation sind kurze, eindeutige Anweisungen wirksamer als eine Diskussion im Team.", e: "Der Führungsstil richtet sich nach der Situation. Die Nachbesprechung kann dann wieder kooperativ erfolgen." }
]);
